sys_script.script:
(function executeRule(current, previous) {
    // RN-01: cliente precisa ter consentimento LGPD válido
    var cli = new GlideRecord('x_espaco_cliente');
    if (cli.get(current.getValue('cliente'))) {
        var clienteEntity = new ClienteEntity(cli);
        if (!clienteEntity.temConsentimentoValido()) {
            gs.addErrorMessage('Cliente sem consentimento LGPD válido. Agendamento bloqueado.');
            current.setAbortAction(true);
            return;
        }
    }

    // RN-02: conflito de horário do mesmo profissional
    var agendamentoEntity = new AgendamentoEntity();
    if (agendamentoEntity.existeConflito(current.getValue('profissional'),
                                          current.getValue('data_hora'),
                                          current.getUniqueValue())) {
        gs.addErrorMessage('Profissional já possui agendamento neste horário.');
        current.setAbortAction(true);
        return;
    }
})(current, previous);
